    def metrics(
        self,
        *,
        from_: Union[str, NotGiven] = NOT_GIVEN,
        to: Union[str, NotGiven] = NOT_GIVEN,
        granularity: Union[Literal["hour", "day"], NotGiven] = NOT_GIVEN,
        dimension: Union[str, NotGiven] = NOT_GIVEN,
        domain: Union[str, NotGiven] = NOT_GIVEN,
        stream: Union[str, NotGiven] = NOT_GIVEN,
        provider: Union[str, NotGiven] = NOT_GIVEN,
        tag: Union[str, NotGiven] = NOT_GIVEN,
        extra_headers: Optional[Mapping[str, str]] = None,
        timeout: Union[float, None, NotGiven] = NOT_GIVEN,
        max_retries: Optional[int] = None,
    ) -> Metrics:
        """Metrics by domain, stream, tag or provider.

        Delivery and engagement of live mail by sending domain, stream, tag or mailbox provider, with rates
        and a time series. Requires a full-access key. Counts are recipients, except delayed, opened and
        clicked: unique emails. Delivery and bounce rates are of sent; complaint, open and click rates of
        delivered. Test-mode mail is excluded. Kept for 400 days. An out-of-band bounce (a later bounce email
        from the remote server) has no sending domain: it is grouped under an empty value. Totals and the
        series count each email once whatever the dimension; with dimension=tag an email with several tags
        appears in each of its tags' groups.

        Args:
            from_: RFC 3339 start. At most 400 days before to. Default: 7 days ago. Sent as "from".
            to: RFC 3339 end (exclusive). Default: now.
            granularity: hour (ranges up to 31 days) or day for series. Default: hour up to 48 hours, else
                day.
            dimension: domain, stream, tag or provider: adds groups, one row per value, busiest first.
            domain: Only this sending (From) domain.
            stream: transactional or broadcast.
            provider: Gmail, Microsoft, Yahoo, Apple or Other.
            tag: Only emails with this tag, as name=value. Cannot be combined with domain, stream or
                provider, and groups only by tag.
            extra_headers: Headers sent with this request only.
            timeout: Seconds this request may take per attempt (default: the client's).
            max_retries: Retries of this request (default: the client's).
        """
        return self._client._request(
            "GET",
            "/metrics",
            query={
                "from": from_,
                "to": to,
                "granularity": granularity,
                "dimension": dimension,
                "domain": domain,
                "stream": stream,
                "provider": provider,
                "tag": tag,
            },
            cast=Metrics,
            options=RequestOptions(extra_headers=extra_headers, timeout=timeout, max_retries=max_retries),
        )


