    def update(
        self,
        id: str,
        *,
        open_tracking: Union[bool, NotGiven] = NOT_GIVEN,
        click_tracking: Union[bool, NotGiven] = NOT_GIVEN,
        tls: Union[str, NotGiven] = NOT_GIVEN,
        reply_tracking: Union[bool, NotGiven] = NOT_GIVEN,
        reply_domain: Union[str, NotGiven] = NOT_GIVEN,
        reply_forward_to: Union[str, NotGiven] = NOT_GIVEN,
        extra_headers: Optional[Mapping[str, str]] = None,
        timeout: Union[float, None, NotGiven] = NOT_GIVEN,
        max_retries: Optional[int] = None,
    ) -> Domain:
        """Update a domain.

        Set the domain's tracking defaults (opens, clicks, replies) and its outbound TLS policy. Requires a
        full-access live key; test keys get 403 test_key_restricted. Fields left out keep their value. The
        response is the domain, as in GET /domains/{id}. Reply tracking: each tracked email gets its own
        signed Reply-To, e.g. r1-<email id>.<signature>@reply.acme.com, so replies come back tied to the exact
        email. Each reply fires email.replied (classified as a person, out-of-office, unsubscribe request,
        bounce…) and arrives as a received email; only replies a person wrote are forwarded. The display name
        is kept (the Reply-To’s name, else the From name). One reply address takes at most 100 replies a day.

        Args:
            id: Domain id
            open_tracking: Default open tracking for emails from this domain.
            click_tracking: Default click tracking for emails from this domain.
            tls: Outbound encryption: opportunistic (default: encrypt whenever offered), required (TLS or
                no delivery) or verified (TLS with a valid certificate). Limits: other values → 422
                invalid_parameter "tls must be opportunistic, required or verified"
            reply_tracking: Default reply tracking for emails from this domain (override per email with
                tracking.replies). Limits: true without a reply_domain → 422 invalid_parameter "reply_tracking
                needs a reply_domain: add an inbound domain such as reply.<domain> first"
            reply_domain: Where tracked reply addresses live: one of your inbound domains, MX-verified,
                equal to this domain or a subdomain of it (e.g. reply.acme.com). "" clears it. Limits:
                otherwise 422 invalid_parameter
            reply_forward_to: Where replies a person wrote are forwarded: a plain address on one of your
                verified domains, or a confirmed forward destination; never a receiving address. "" (default)
                forwards to the email’s first Reply-To, else its From. Limits: otherwise 422 invalid_parameter
            extra_headers: Headers sent with this request only.
            timeout: Seconds this request may take per attempt (default: the client's).
            max_retries: Retries of this request (default: the client's).
        """
        return self._client._request(
            "PATCH",
            "/domains/{id}",
            path_params={"id": id},
            body={
                "open_tracking": open_tracking,
                "click_tracking": click_tracking,
                "tls": tls,
                "reply_tracking": reply_tracking,
                "reply_domain": reply_domain,
                "reply_forward_to": reply_forward_to,
            },
            cast=Domain,
            options=RequestOptions(extra_headers=extra_headers, timeout=timeout, max_retries=max_retries),
        )

