        domain_id: Union[Optional[str], NotGiven] = NOT_GIVEN,
        stream: Union[Optional[Literal["transactional", "broadcast"]], NotGiven] = NOT_GIVEN,
        extra_headers: Optional[Mapping[str, str]] = None,
