class VariablesResource(SyncResource):
    """variables: operations of client.variables."""

    @property
    def with_response(self) -> VariablesResourceWithResponse:
        """These operations, returning an APIResponse: the result with the status, headers and request id."""
        return VariablesResourceWithResponse(self)

    def list(
        self,
        *,
        extra_headers: Optional[Mapping[str, str]] = None,
        timeout: Union[float, None, NotGiven] = NOT_GIVEN,
        max_retries: Optional[int] = None,
    ) -> SyncPage[Variable]:
        """List variables.

        The variable catalogue: every variable the account’s templates can use, with where each is used.
        System variables first, then global ones, then template variables, each sorted by name. Requires a
        full-access key. kind is system (filled by ZapSMTP), global (set for the account, written
        {{global.key}}) or template (a template’s own). A global variable that templates use but that has no
        value yet is listed without value; sends with those templates fail until you set it. A template
        variable lists in types every type its templates declare, and per template its type, required, default
        and unused (declared, but the source no longer names it).

        Returns the first page; iterate it for every item of every page.

        Args:
            extra_headers: Headers sent with this request only.
            timeout: Seconds this request may take per attempt (default: the client's).
            max_retries: Retries of this request (default: the client's).
        """
        return self._client._request_page(
            "GET",
            "/variables",
            cast=Variable,
            paging=None,
            options=RequestOptions(extra_headers=extra_headers, timeout=timeout, max_retries=max_retries),
        )

    def set_global(
        self,
        key: str,
        *,
        value: Union[str, NotGiven] = NOT_GIVEN,
        description: Union[str, NotGiven] = NOT_GIVEN,
        extra_headers: Optional[Mapping[str, str]] = None,
        timeout: Union[float, None, NotGiven] = NOT_GIVEN,
        max_retries: Optional[int] = None,
    ) -> Variable:
        """Set a global variable.

        Create or replace a global variable. Every template that uses it renders the new value from the next
        send on. Requires a full-access live key; test keys get 403 test_key_restricted. The response does not
        list the templates using the variable; GET /variables does.

        Args:
            key: The key, used as {{global.key}}: letters, digits, _ and -, starting with a letter or _,
                up to 64; global is reserved. Limits: other keys → 422 invalid_parameter
            value: The value, always a string. Limits: at most 10 KB → 422 invalid_parameter Default: "".
            description: What it is for. Limits: at most 500 bytes → 422 invalid_parameter
            extra_headers: Headers sent with this request only.
            timeout: Seconds this request may take per attempt (default: the client's).
            max_retries: Retries of this request (default: the client's).
        """
        return self._client._request(
            "PUT",
            "/variables/global/{key}",
            path_params={"key": key},
            body={"value": value, "description": description},
            cast=Variable,
            options=RequestOptions(extra_headers=extra_headers, timeout=timeout, max_retries=max_retries),
        )

    def delete_global(
        self,
        key: str,
        *,
        extra_headers: Optional[Mapping[str, str]] = None,
        timeout: Union[float, None, NotGiven] = NOT_GIVEN,
        max_retries: Optional[int] = None,
    ) -> Deleted:
        """Delete a global variable.

        Delete a global variable. Sends with a template that still uses it then fail with 422
        template_render_error until it is set again. Requires a full-access live key; test keys get 403
        test_key_restricted.

        Args:
            key: The key, used as {{global.key}}: letters, digits, _ and -, starting with a letter or _,
                up to 64; global is reserved. Limits: other keys → 422 invalid_parameter
            extra_headers: Headers sent with this request only.
            timeout: Seconds this request may take per attempt (default: the client's).
            max_retries: Retries of this request (default: the client's).
        """
        return self._client._request(
            "DELETE",
            "/variables/global/{key}",
            path_params={"key": key},
            cast=Deleted,
            options=RequestOptions(extra_headers=extra_headers, timeout=timeout, max_retries=max_retries),
        )


